firmware:
// TANG R6 firmware sketch, Teensy 4.0. Generated by the TANG R6 bench.
// Mode: TEENSY, pads: CAP, pots: printed, slider track on the undefined.
// No discrete resistors: pads use the internal pull up and RC charge timing, the slide and the pots are
// ratiometric printed tracks, pressure uses the internal pull up on the wiper pin.
#include <Audio.h>
const int PAD_PIN[6] = {7, 8, 9, 12, 11, 10};   // A1 A2 A3 B1 B2 B3
const int NECK_W = 22;                      // slider wiper (analog)
const int POT_W[3] = {18, 15, 14};   // printed pot wipers (analog)

// slide track ends are on the 3V3 and GND buses of the face; nothing to drive.

// ---- capacitive pads: charge time through the internal pull up (about 22k on Teensy 4.0)
uint32_t padTime(int p) {
  pinMode(p, OUTPUT); digitalWriteFast(p, LOW); delayMicroseconds(20);   // pre discharge
  noInterrupts();
  pinMode(p, INPUT_PULLUP);
  uint32_t t0 = ARM_DWT_CYCCNT;
  while (!digitalReadFast(p) && (ARM_DWT_CYCCNT - t0) < 200000) {}
  uint32_t dt = ARM_DWT_CYCCNT - t0;
  interrupts();
  pinMode(p, OUTPUT); digitalWriteFast(p, LOW);
  return dt;                                    // cycles at 600 MHz; touched pads read 2 to 4 times longer
}
uint32_t padBase[6]; bool padOn[6];
void padsInit() { ARM_DEMCR |= ARM_DEMCR_TRCENA; ARM_DWT_CTRL |= ARM_DWT_CTRL_CYCCNTENA; for (int i = 0; i < 6; i++) { uint32_t s = 0; for (int k = 0; k < 16; k++) s += padTime(PAD_PIN[i]); padBase[i] = s / 16; } }
void padsScan() { for (int i = 0; i < 6; i++) { uint32_t t = padTime(PAD_PIN[i]); bool on = t > padBase[i] * 3 / 2; if (!on) padBase[i] = (padBase[i] * 31 + t) / 32; padOn[i] = on; } }

// ---- slider: position, then pressure
// phase A: plain read of the wiper, ratiometric between the 3V3 and GND ends of the printed track
// no touch: the wiper floats. Pre discharge it and see if it stays low.
int slidePos = -1; int slidePressure = 0;
void slideRead() {
  pinMode(NECK_W, OUTPUT); digitalWriteFast(NECK_W, LOW); delayMicroseconds(10); pinMode(NECK_W, INPUT);
  delayMicroseconds(30);
  int v = analogRead(NECK_W);
  if (v < 12) { slidePos = -1; slidePressure = 0; return; }   // stayed near ground: nothing touching
  slidePos = v;                                              // 0..1023 (set analogReadResolution for more)
  // phase B: enable the internal pull up and read again. The wiper now sees the track ends' parallel
  // resistance (position dependent, subtract it) plus the contact resistance, which drops with pressure.
  pinMode(NECK_W, INPUT_PULLUP); delayMicroseconds(30);
  int vb = analogRead(NECK_W);
  pinMode(NECK_W, INPUT);
  slidePressure = 1023 - vb;                                 // bigger when pressed harder
}

// ---- printed pots: ratiometric, calibrate the end stops once (turn each fully both ways at power up)
int potMin[3] = {40, 40, 40}, potMax[3] = {1000, 1000, 1000};
int potRead(int k) { int v = analogRead(POT_W[k]); if (v < potMin[k]) potMin[k] = v; if (v > potMax[k]) potMax[k] = v; return map(v, potMin[k], potMax[k], 0, 1023); }

// ---- audio: MAX98357A on I2S2 (BCLK pin 4, LRCLK pin 3, DIN pin 2), hand wired to the pin tails. I2S1 would
// take pin 7, which is a pad drive here.
AudioSynthWaveform osc; AudioOutputI2S2 i2s; AudioConnection c1(osc, 0, i2s, 0); AudioConnection c2(osc, 0, i2s, 1);
void setup() {
  AudioMemory(12); analogReadResolution(10); analogReadAveraging(4);
  padsInit(); osc.begin(0.4, 220, WAVEFORM_TRIANGLE);
}
void loop() {
  padsScan(); slideRead();
  if (slidePos >= 0) osc.frequency(110.0 * powf(2.0, slidePos / 1023.0 * 2.0));
  float amp = potRead(0) / 1023.0; osc.amplitude(amp * 0.6);
  delay(5);
}
